"use client";
/* Candle, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Candle(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("candle"); }, []);
  return React.createElement("piix-sprite", { "name": "candle", ...piixAttrs(props) });
}

export default Candle;
